theorem continuousOn_primitive_of_integrableOn {T : ℝ} {v : ℝ → X}
    (hv : IntegrableOn v (Set.Icc 0 T) volume) :
    ContinuousOn (fun t => ∫ s in (0:ℝ)..t, v s) (Set.Icc 0 T)

theorem FieldForms.forwardGlobalSolution_exists (D : FieldForms V) {ν : ℝ}
    (hν : 0 < ν) (x₀ : V) :
    ∃ c : ℝ → V, c 0 = x₀ ∧ ∀ t, 0 ≤ t → HasDerivAt c (D.vectorField ν (c t)) t
